// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * Ways to get help as cards or rows, each with an icon, a title, a sentence and an open link. Axes: layout
 * (grid, list), columns, action (link, none), tone (default, muted).
 */
import { type ReactNode } from "react";
import { Card, CardContent, Grid, Stack, Text, Title } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { EmptyState } from "../components/empty-state";
import { MenuEntry } from "../components/menu-entry";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Feature } from "./feature-grid.types";

export type SupportChannelsProps = {
  id: string;
  title: string;
  channels: Feature[];
  empty?: string;
  open: string;
  layout?: "grid" | "list";
  cols?: "1-2" | "1-3";
  action?: "link" | "none";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function SupportChannels({
  id,
  title,
  channels,
  empty = "",
  open,
  layout = "grid",
  cols = "1-3",
  action = "link",
  tone = "default",
  landmarkLabel,
}: SupportChannelsProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} landmarkLabel={landmarkLabel}>
      {((channels?.length ?? 0) === 0) ? (
        <EmptyState icon="life-buoy" title={empty} />
      ) : (
        <Grid cols={(((layout as string) === "list") ? "1" : cols)} className="gap-4" data-slot="items">
          {(channels ?? []).map((c) => (
            <Card key={c.id}
              variant="default"
              className={cn("h-full", (((layout as string) === "list") ? "flex-row items-center" : ""))}
            >
              <CardContent className={cn("flex flex-1 gap-4", (((layout as string) === "list") ? "items-center" : "flex-col"))}>
                <LucideIcon name={c.icon} size={24} />
                <Stack gap="2" className="flex-1">
                  <Title as={3} size="base" weight="bold">
                    {c.title}
                  </Title>
                  <Text size="sm" className="text-muted-foreground">
                    {c.text}
                  </Text>
                </Stack>
                {((action as string) === "link") ? (
                  <MenuEntry href={c.href} className="font-semibold" testid="open">
                    {open}
                  </MenuEntry>
                ) : null}
              </CardContent>
            </Card>
          ))}
        </Grid>
      )}
    </SectionFrame>
  );
}
